/**
 * Confirmation before a destructive action (D39). [confirmText] repeats the verb („Löschen“), never „OK“ or „Ja“.
 * The same dialog asks before a final step that deletes nothing (D102 (43), spec/02 §4.6: „Retro beenden?“); its [text] then
 * says what is no longer possible afterwards, not „Das lässt sich nicht rückgängig machen.“.
 * Back, Escape and the scrim cancel. Behind it the palette's scrim (D99 (4): light 32 %, as the web's backdrop), not
 * the platform's 60 % black. [haptics] = false: the app's „Vibration“ switch is off, confirming stays silent (D105 (24)).
 * [neutral] = true (D105 (37), spec/02 §4.6): nothing is lost by the step, so the verb is an SbSecondaryAction and no pulse
 * plays.
 */
@Composable
fun SbConfirmDialog(
    title: String,
    text: String,
    confirmText: String,
    onConfirm: () -> Unit,
    onDismiss: () -> Unit,
    dismissText: String = sbMessages().cancel,
    haptics: Boolean = true,
    neutral: Boolean = false,
) {
    SbConfirmDialog(AnnotatedString(title), AnnotatedString(text), confirmText, onConfirm, onDismiss, dismissText, haptics, neutral)
}

/**
 * [SbConfirmDialog] with formatted [title] and [text] (§8, 2026-10-26; provisional, agent): a file name marked
 * with sbFileName breaks only after - . _ / (§16), a struck or bold span stays; both wrap as SbWrapText.
 */
@Composable
fun SbConfirmDialog(
    title: AnnotatedString,
    text: AnnotatedString,
    confirmText: String,
    onConfirm: () -> Unit,
    onDismiss: () -> Unit,
    dismissText: String = sbMessages().cancel,
    haptics: Boolean = true,
    neutral: Boolean = false,
) {
    val pulse = rememberSbHaptics(haptics)
    SbDialogFrame(title, text, onDismiss) {
        SbSecondaryAction(dismissText, onDismiss)
        if (neutral) {
            SbSecondaryAction(confirmText, onConfirm)
        } else {
            SbDangerAction(confirmText, onClick = {
                pulse.deleteConfirmed()
                onConfirm()
            })
        }
    }
}

/**
 * Unsaved changes, three ways (D105 (36); spec/02 §4.6): „Abbrechen“ first, „Verwerfen“ (SbDangerAction without
 * the trash: the changes go, the file stays) and „Sichern“ last as an SbSecondaryAction (no lime in a dialog; AKT-11).
 * Wrapping keeps that order, end-aligned. [onDiscard] plays the stronger pulse as a deletion does, only with [haptics];
 * „Sichern unter …“ is never offered here. [saveHint] = the data-path line directly under „Sichern“ (D98 V4, spec/10
 * §3.4): sbMessages().staysOnDevice or the app's own line; caption, textMuted, read right after the key; null shows
 * none. Key and line end-aligned (D113): „Sichern“ ends flush with the other keys, the line ends with it, also when it
 * is wider, and wraps end-aligned inside the row.
 */
@Composable
fun SbUnsavedDialog(
    title: String,
    text: String,
    onSave: () -> Unit,
    onDiscard: () -> Unit,
    onDismiss: () -> Unit,
    saveText: String = sbMessages().save,
    discardText: String = sbMessages().discard,
    dismissText: String = sbMessages().cancel,
    haptics: Boolean = true,
    saveHint: String? = null,
    saveEnabled: Boolean = true,
) {
    SbUnsavedDialog(AnnotatedString(title), AnnotatedString(text), onSave, onDiscard, onDismiss, saveText, discardText, dismissText, haptics, saveHint, saveEnabled)
}

/** [SbUnsavedDialog] with formatted [title] and [text] (a file name marked with sbFileName, §16). */
@Composable
fun SbUnsavedDialog(
    title: AnnotatedString,
    text: AnnotatedString,
    onSave: () -> Unit,
    onDiscard: () -> Unit,
    onDismiss: () -> Unit,
    saveText: String = sbMessages().save,
    discardText: String = sbMessages().discard,
    dismissText: String = sbMessages().cancel,
    haptics: Boolean = true,
    saveHint: String? = null,
    saveEnabled: Boolean = true,
) {
    val pulse = rememberSbHaptics(haptics)
    SbDialogFrame(title, text, onDismiss) {
        SbSecondaryAction(dismissText, onDismiss)
        SbDangerAction(discardText, onClick = {
            pulse.deleteConfirmed()
            onDiscard()
        })
        if (saveHint == null) {
            SbSecondaryAction(saveText, onSave, enabled = saveEnabled)
        } else {
            // the key and its line in one column: TalkBack reads the line right after „Sichern“ (spec/10 §3.4); both
            // end-aligned (D113), the line wraps inside the row's width with its lines end-aligned
            Column(
                horizontalAlignment = Alignment.End,
                verticalArrangement = Arrangement.spacedBy(SebaroTheme.tokens.space.s2),
            ) {
                SbSecondaryAction(saveText, onSave, enabled = saveEnabled)
                Text(
                    saveHint,
                    style = SebaroTheme.typography.caption,
                    color = SebaroTheme.colors.textMuted,
                    textAlign = TextAlign.End,
                )
            }
        }
    }
}


