/** The frame of the dialogs above: scrim, card, title, the scrolling body and the end-aligned, wrapping actions. */
@Composable
private fun SbDialogFrame(
    title: AnnotatedString,
    text: AnnotatedString,
    onDismiss: () -> Unit,
    actions: @Composable RowScope.() -> Unit,
) {
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val ink = SebaroTheme.colors.text
    val overlay = t.elevation.overlay
    val scrim = SebaroTheme.colors.scrim
    // the dialog window fills the screen and draws the scrim itself: the platform's window dim is black at the
    // theme's amount (60 %) and has no colour of its own, so it is set to 0
    Dialog(
        onDismissRequest = onDismiss,
        properties = DialogProperties(usePlatformDefaultWidth = false, decorFitsSystemWindows = false),
    ) {
        val window = (LocalView.current.parent as? DialogWindowProvider)?.window
        SideEffect { window?.setDimAmount(0f) }
        Box(Modifier.fillMaxSize()) {
            // a tap on the scrim cancels; the card above it takes its own taps (a sibling, not a parent)
            Box(
                Modifier
                    .matchParentSize()
                    .background(scrim)
                    .pointerInput(onDismiss) { detectTapGestures(onTap = { onDismiss() }) },
            )
            BoxWithConstraints(
                Modifier
                    .fillMaxSize()
                    .windowInsetsPadding(WindowInsets.systemBars.union(WindowInsets.ime))
                    .padding(horizontal = t.spacing.gutter),
                contentAlignment = Alignment.Center,
            ) {
                val most = constraints.maxHeight
                val sheet = rememberScrollState()
                var whole by remember { mutableStateOf(false) }
                val words = rememberScrollState()
                val wordsEnd = remember { mutableIntStateOf(0) }
                val bodyLines = with(LocalDensity.current) { ty.body.lineHeight.roundToPx() } * 2
                // the window gives its focus to the first key, so that words cut off pass unread: with keys a cut sheet or
                // body starts at its own stop, and Down reads on to the keys
                val sheetFocus = remember { FocusRequester() }
                val wordsFocus = remember { FocusRequester() }
                LaunchedEffect(whole) {
                    snapshotFlow { if (whole) sheet.canScrollForward else words.canScrollForward }.sbFirstVisible { it }
                    (if (whole) sheetFocus else wordsFocus).requestFocus()
                }
                Surface(
                    modifier = Modifier.widthIn(max = 560.dp),
                    shape = t.shapes.sheet,
                    color = overlay.surface,
                    contentColor = SebaroTheme.colors.text,
                    border = BorderStroke(overlay.borderWidth, overlay.borderColor),
                    shadowElevation = overlay.shadowElevation,
                ) {
                    // spec/02 §4.6: only the body scrolls when the card is taller than the screen, title and actions stay. Where
                    // they leave the body less than two lines, the whole sheet scrolls, so nothing lies out of reach (CHECKS.md §93).
                    // Only then: a scroller keeps a stop for the keys and a node for TalkBack
                    Layout(
                        content = {
                            SbWrapText(title, ty.title, ink, Modifier.semantics { heading() })
                            // mark, fade and keys as any cut area: the sentence that ends mid-way says what is lost (CHECKS.md §95)
                            SbWrapText(
                                text,
                                ty.body,
                                ink,
                                Modifier
                                    .sbScrollMark(words, SebaroTheme.colors.borderStrong, outside = t.space.s3)
                                    .focusRequester(wordsFocus)
                                    .sbScrollKeys(words)
                                    .verticalScroll(words),
                            )
                            SbFlowRow(
                                Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(t.space.s3, Alignment.End),
                                verticalArrangement = Arrangement.spacedBy(t.space.s3),
                                content = actions,
                            )
                        },
                        // inside the card's edge, which draws over what it holds: the mark and the ring would lie under it. The
                        // fade only while words are cut, so it never lies on a key
                        modifier = (if (whole) {
                            Modifier
                                .padding(overlay.borderWidth)
                                // the stop would take Back and Escape from a key inside it, as a step out: the question closes (CHECKS.md §96)
                                .onPreviewKeyEvent { e ->
                                    if (e.key != Key.Escape && e.key != Key.Back) return@onPreviewKeyEvent false
                                    if (e.type == KeyEventType.KeyDown) onDismiss()
                                    true
                                }
                                // off the edge, which in the dark has the mark's colour
                                .sbScrollMark(sheet, SebaroTheme.colors.borderStrong, outside = -t.space.s1, unseen = { wordsEnd.intValue - sheet.value - sheet.viewportSize })
                                .focusRequester(sheetFocus)
                                .sbScrollKeys(sheet)
                                .verticalScroll(sheet)
                        } else {
                            Modifier
                        }).padding(t.space.s6),
                    ) { measurables, constraints ->
                        val w = constraints.maxWidth
                        val free = constraints.copy(minWidth = 0, minHeight = 0, maxHeight = Constraints.Infinity)
                        val head = measurables[0].measure(free)
                        val keys = measurables[2].measure(free)
                        val above = t.space.s3.roundToPx()
                        val under = t.space.s6.roundToPx()
                        val room = most - 2 * under - head.height - above - under - keys.height
                        whole = room < bodyLines
                        // the body's own verticalScroll takes no unbounded height: this one is never reached
                        val body = measurables[1].measure(free.copy(maxHeight = if (whole) 32_000 else room))
                        wordsEnd.intValue = under + head.height + above + body.height
                        val all = head.height + above + body.height + under + keys.height
                        layout(w, constraints.constrainHeight(all)) {
                            head.placeRelative(0, 0)
                            body.placeRelative(0, head.height + above)
                            keys.placeRelative(0, head.height + above + body.height + under)
                        }
                    }
                }
            }
        }
    }
}
